```tsx
import { useId } from "react";
import "./FocusProgress.css";

export interface FocusProgressProps {
  label: string;
  elapsedMinutes: number;
  totalMinutes: number;
}

export function FocusProgress({ label, elapsedMinutes, totalMinutes }: FocusProgressProps) {
  const labelId = useId();

  const total = Number.isFinite(totalMinutes) ? Math.max(totalMinutes, 0) : 0;
  const elapsed = Number.isFinite(elapsedMinutes)
    ? Math.min(Math.max(elapsedMinutes, 0), total)
    : 0;
  const percent = total > 0 ? (elapsed / total) * 100 : 0;

  const shownElapsed = Math.round(elapsed);
  const shownTotal = Math.round(total);

  return (
    <div className="focus-progress">
      <div className="focus-progress__head">
        <span id={labelId} className="focus-progress__label">
          {label}
        </span>
        <span className="focus-progress__count">
          {shownElapsed} / {shownTotal} min
        </span>
      </div>
      <div
        role="progressbar"
        aria-labelledby={labelId}
        aria-valuemin={0}
        aria-valuemax={shownTotal}
        aria-valuenow={shownElapsed}
        aria-valuetext={`${shownElapsed} of ${shownTotal} minutes`}
        className="focus-progress__track"
      >
        <div className="focus-progress__fill" style={{ width: `${percent}%` }} />
      </div>
    </div>
  );
}
```

