.focus-progress {
  display: grid;
  gap: clamp(0.4rem, 0.8vw, 0.6rem);
  font: inherit;
  color: var(--ink);
}

.focus-progress__head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1rem;
}

.focus-progress__label {
  font-size: clamp(0.95rem, 1.2vw, 1.1rem);
  font-weight: 600;
  color: var(--ink);
}

.focus-progress__count {
  font-size: clamp(0.85rem, 1vw, 1rem);
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.focus-progress__track {
  position: relative;
  height: clamp(0.5rem, 0.9vw, 0.75rem);
  border-radius: 999px;
  background: var(--axon-ahead);
  overflow: hidden;
}

.focus-progress__fill {
  height: 100%;
  border-radius: 999px;
  background: var(--myelin);
  transition: width 400ms ease-out;
}

@media (prefers-reduced-motion: reduce) {
  .focus-progress__fill {
    transition: none;
  }
}

:root[data-motion="reduce"] .focus-progress__fill {
  transition: none;
}
